mapper.update:
UPDATE admin_notices
SET link_url = #{linkUrl},
    updated_by = #{updatedBy}
WHERE id = #{id}

UPDATE admin_notices
SET active = FALSE,
    updated_by = #{updatedBy}
WHERE id = #{id}

mapper.insert:
INSERT INTO notifications(notice_id, recipient_user_id, sender_user_id, type, title, body, link_url)
SELECT an.id, u.id, #{senderUserId}, 'ADMIN_NOTICE', an.title, #{body}, #{linkUrl}
FROM admin_notices an
JOIN users u ON u.active = TRUE
WHERE an.id = #{noticeId}

mapper.update:
UPDATE notifications
SET read_at = COALESCE(read_at, NOW())
WHERE id = #{notificationId}
  AND recipient_user_id = #{userId}

mapper.delete:
DELETE FROM notifications
WHERE id = #{notificationId}
  AND recipient_user_id = #{userId}

mapper.update:
UPDATE notifications
SET read_at = COALESCE(read_at, NOW())
WHERE notice_id = #{noticeId}
  AND recipient_user_id = #{userId}
  AND read_at IS NULL

mapper.select:
SELECT COALESCE((
    SELECT TRUE
    FROM message_room_members
    WHERE room_id = #{roomId}
      AND user_id = #{userId}
), FALSE)

mapper.delete:
DELETE FROM message_room_members
WHERE room_id = #{roomId}
  AND user_id = #{userId}

mapper.update:
UPDATE message_rooms
SET updated_at = NOW()
WHERE id = #{roomId}

mapper.select:
SELECT ma.id, ma.message_id, ma.room_id, ma.original_filename, ma.stored_filename,
       ma.content_type, ma.file_size, ma.attachment_type, ma.expires_at, ma.created_at
FROM message_attachments ma
JOIN message_room_members mrm ON mrm.room_id = ma.room_id AND mrm.user_id = #{userId}
WHERE ma.id = #{attachmentId}
LIMIT 1

SELECT MAX(id)
FROM message_messages
WHERE room_id = #{roomId}

mapper.update:
UPDATE message_room_members
SET last_read_message_id = #{messageId}
WHERE room_id = #{roomId}
  AND user_id = #{userId}
  AND COALESCE(last_read_message_id, 0) < #{messageId}

mapper.select:
SELECT user_id
FROM message_room_members
WHERE room_id = #{roomId}
  AND user_id != #{senderUserId}

SELECT COALESCE((
    SELECT muted
    FROM message_room_user_settings
    WHERE room_id = #{roomId}
      AND user_id = #{userId}
), FALSE)
